(566, 'G147', 0, 8, 1, 'Bachelor in Computer Application (PREMIUM)', 'under-graduation-bachelor-in-computer-application-premium', '', '', 'Explore advanced computing with the Premium BCA program. Learn programming, app development, AI, data science, and more at our top-rated institute.', 'premium BCA course, bachelor in computer application, BCA in AI, BCA in data science, computer programming course, app development, IT degree, best BCA college in Gujarat', '', 'Premium Bachelor in Computer Application (BCA) – Institute of Computer Application', '', '', '', 30, '4', 79000, 41900, 39500, 39850, 39500, 39850, 39500, 39850, 42500, NULL, NULL, NULL, 0, 6000, 6000, 0, 0, 0, NULL, NULL, NULL, '', '', 1, 0, '2024-12-27 08:26:12', '2025-06-18 12:05:19', NULL, NULL),
(567, 'G89', 0, 5, 1, 'Finance, Marketing and Human Resource Mngt', 'under-graduation-bachelor-in-business-administration-premium', '', '', 'Study BBA with specialization in Finance, Marketing, and Human Resource Management. Build a strong foundation in business, leadership, and strategy.', 'BBA in finance, BBA in marketing, BBA in HR, management degree, business administration, business leadership course, BBA program Gujarat, undergraduate business program', '', 'BBA in Finance, Marketing & HR Management – Institute of Management', '', '', '', 30, '4', 79000, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 11000, 6000, 0, 0, 0, NULL, NULL, NULL, '', '', 0, 0, '2024-12-27 08:27:40', '2025-06-18 12:05:19', NULL, NULL),
