(569, 'G80', 0, 4, 1, 'Corporate Financial Management (CA aliened Syllabus) (PREMIUM)', 'under-graduation-bachelor-of-commerce-premium', '', '', 'Enroll in our premium Corporate Financial Management program aligned with the CA syllabus. Master accounting, taxation, auditing, and corporate finance.', 'corporate financial management, CA aligned course, premium commerce program, taxation, auditing, accounting, financial analysis, B.Com CA integrated, best commerce college in Gujarat', '', 'Premium Corporate Financial Management (CA Aligned) – Institute of Commerce', '', '', '', 30, '4', 72000, 38400, 36000, 36350, 36000, 36350, 36000, 36350, 39000, NULL, NULL, NULL, 0, 6000, 6000, 0, 0, 0, NULL, NULL, NULL, '', '', 1, 0, '2024-12-27 08:29:51', '2025-06-18 12:05:19', NULL, NULL),
(570, 'G115', 0, 6, 1, 'Psychology (PREMIUM)', 'under-graduation-bachelor-of-arts-premium', '', '', 'Study human behavior with our premium BA in Psychology program. Learn cognitive science, clinical psychology, and research methods in a practical setting.', 'BA psychology, premium psychology course, undergraduate psychology, clinical psychology, behavioral science, cognitive psychology, arts and humanities degree, best psychology college', '', 'Premium BA in Psychology – Institute of Arts', '', '', '', 30, '4', 72000, 38400, 36000, 36350, 36000, 36350, 36000, 36350, 39000, NULL, NULL, NULL, 0, 6000, 6000, 0, 0, 0, NULL, NULL, NULL, '', '', 1, 0, '2024-12-27 08:30:41', '2025-06-18 12:05:19', NULL, NULL),
